{\"p\":[{\"id\":\"A08-P01\",\"title\":\"Înregistrare, rutare și izolare fizică\",\"tasks\":[\"P01.C10.T0002\",\"P01.C10.T0018\",\"P01.C10.T0019\",\"P01.C10.T0025\"],\"trigger\":\"Configurarea unui nou canal sau redenumirea canalului\",\"actor\":\"Administrator cabinet A și administrator firmă A1\",\"ui\":\"Setări canal → /CUI_A → /CUI_A/CUI_A1 → /CUI_A/CUI_A1/Magazin1\",\"be\":\"Traefik → rezolvare slug și identitate stabilă → serviciu Docker al canalului → identitate autorizată\",\"db\":\"EVA_CanalVanzare, AD_Client/Org; volume PostgreSQL, Redis, Meilisearch și ActiveStorage inventariate individual\",\"states\":\"definit → provisionat → verificat → activ / suspendat / revenire la versiune\",\"fault\":\"CUI editat, slug dublu, instanță nesănătoasă, depanare fără fallback către alt canal\",\"oracle\":\"Un site logic și o instanță Docker identificate pentru fiecare canal, inclusiv eMag/Trendyol. Date private canar A nu apar niciodată în B.\",\"owners\":\"A01 acces, A02 identități, A10 medii\"},{\"id\":\"A08-P02\",\"title\":\"Publicare catalog de canal și ofertă G3\",\"tasks\":[\"P01.C10.T0002\",\"P01.C10.T0007\",\"P01.C10.T0017\",\"P01.C10.T0018\",\"P01.C10.T0028\",\"P01.C10.T0029\"],\"trigger\":\"Responsabilul publică o modificare din tabela produs × canal\",\"actor\":\"Responsabilul de canal și client comercial\",\"ui\":\"ERP Fișă pe canal → catalog → fișă produs în site → API coș\",\"be\":\"Reguli de canal și disponibil A06 → copiere publică mapată prin ID intern → cache, filtrare pe canal și timp\",\"db\":\"EVA_CanalVanzare; M_Product, M_PriceList/Version și date sursă G3, catalog public identificat la inventar\",\"states\":\"ciornă → publicabil → publicat → expirat/dezactivat\",\"fault\":\"Mesaje întârziate, lipsă traducere sau legătură produs, cache după schimbare de canal\",\"oracle\":\"Prețul public și termenul coincid cu versiunea sursă. P1/CPA arată alt ID față de P1/CPP. 120 componente din fiecare permit maxim 20 S1 sau 40 S2 înainte de alte angajamente.\",\"owners\":\"A06 ofertă/rezervări, A05 disponibil fizic, A02 model\"},{\"id\":\"A08-P03\",\"title\":\"Coș, checkout și înregistrare ERP\",\"tasks\":[\"P01.C10.T0003\",\"P01.C10.T0007\",\"P01.C10.T0017\",\"P01.C10.T0018\",\"P01.C10.T0025\"],\"trigger\":\"Utilizatorul sau comisionarul confirmă o comandă online\",\"actor\":\"B2C, B2B, comisionar al canalului\",\"ui\":\"Produs → coș → adrese și transport → revizuire → confirmare și număr de referință\",\"be\":\"Serviciu checkout comun → referință externă → import comercial al ERP → C_Order/C_OrderLine → răspuns persistent\",\"db\":\"Comandă de canal și legătură externă, C_BPartner/Location, C_Order/Line, M_PriceList, C_Currency/C_Tax\",\"states\":\"coș → ofertă recalculată → trimis → primit în ERP / în verificare / refuz\",\"fault\":\"Dublu clic, răspuns pierdut după commit, schimbare preț/stoc ori două canale folosesc același ID extern\",\"oracle\":\"O cheie stabilă pe firmă+canal+comandă produce un singur antet. Acceptarea comenzii nu produce pick/aviz/AWB/factură în site.\",\"owners\":\"A06 import și rezervare, A05 pick, A07 documente, A01 drepturi\"},{\"id\":\"A08-P04\",\"title\":\"Comisionar și situațiile proprii\",\"tasks\":[\"P01.C10.T0004\",\"P01.C10.T0005\",\"P01.C10.T0012\",\"P01.C10.T0017\",\"P01.C10.T0025\"],\"trigger\":\"Comisionarul autentificat consultă o comandă sau raport\",\"actor\":\"Comisionar A; comisionar B în același canal; responsabil ERP\",\"ui\":\"Cont → comenzile mele → situație comision → detaliu, retur solicitat sau export\",\"be\":\"Autorizare per sesiune → filtru server persoană+client+org+canal → proiecție ERP → răspuns\",\"db\":\"C_BPartner, C_Order, C_Invoice, alocări/retur și cheie comisionar; tabele efective confirmate în mediul izolat\",\"states\":\"comandă proprie → stare din ERP → raport la dată → export\",\"fault\":\"ID injectat sau alt canal; permisiune revocată; filtru UI ocolit\",\"oracle\":\"Numărul de rânduri, totalul și exportul sunt identice cu referința autorizată. Nici antetul altui comisionar nu este divulgat.\",\"owners\":\"A01 control acces, A06 comisioane, A07 retururi\"},{\"id\":\"A08-P05\",\"title\":\"Temă Cesiro și previzualizare platforme\",\"tasks\":[\"P01.C10.T0002\",\"P01.C10.T0019\",\"P01.C10.T0020\",\"P01.C10.T0021\",\"P01.C10.T0022\",\"P01.C10.T0029\"],\"trigger\":\"Responsabilul configurează modelul și verifică oferta înainte de publicare\",\"actor\":\"Responsabil de canal și cumpărător\",\"ui\":\"Setări → previzualizare eMag/Trendyol sau magazin → card produs → pagină produs pe desktop și mobil\",\"be\":\"Contract comun conținut, temă și mapări media/categorie/atribute/limbă; simulatoare fără apeluri externe\",\"db\":\"Config temă/canal, traduceri și media, identificator versiune previzualizată și catalog publicat\",\"states\":\"schiță → previzualizare privată → validat → publicat / retras\",\"fault\":\"Șablon schimbat cu coș existent; HTML nesigur; produs fără imagini sau atribut obligatoriu\",\"oracle\":\"În preview apar titlu, imagini, preț, disponibil, seller și atribute din același payload. Preview privat nu devine pagină publică și nu trimite către platformă.\",\"owners\":\"A06 mapări, A09 UX, A01 acces, A10 simulatoare\"},{\"id\":\"A08-P06\",\"title\":\"Marketing, localizare și indexare\",\"tasks\":[\"P01.C10.T0004\",\"P01.C10.T0018\",\"P01.C10.T0019\",\"P01.C10.T0029\"],\"trigger\":\"Un client alege limba sau preferințele de analiză și navighează de la campanie\",\"actor\":\"Vizitator cu acord, fără acord și după retragere\",\"ui\":\"Landing → categorie → produs → checkout → modificare preferințe\",\"be\":\"Traduceri și fallback per canal, schemă SEO, canonical/hreflang, sitemap, evenimente condiționate de preferințe\",\"db\":\"Config locale și scop/dată/versiune acord; evenimente și rapoarte agregate pe canal\",\"states\":\"neales → refuzat / acceptat → retras; produs publicat → delistat\",\"fault\":\"Cookie anterior, navigare SPA, cache între limbi, crawler pe cont sau preview, comandă reluată\",\"oracle\":\"Nicio cerere de marketing înainte de acord pentru categoria configurată; un eveniment conversie per comandă în cazul permis; zero URL-uri private în sitemap.\",\"owners\":\"A01 date personale, A06 campanii, A09 accesibilitate, A10 observabilitate\"},{\"id\":\"A08-P07\",\"title\":\"Reconciliere și recuperare a canalului\",\"tasks\":[\"P01.C10.T0003\",\"P01.C10.T0006\",\"P01.C10.T0010\",\"P01.C10.T0011\",\"P01.C10.T0019\",\"P01.C10.T0025\"],\"trigger\":\"Deconectare temporară între canal și ERP sau reluarea unui worker\",\"actor\":\"Operator ERP și responsabil site\",\"ui\":\"Client vede referința/starea → ERP excepții → reconciliere → situație actualizată în site\",\"be\":\"Coadă identificată după versiune → retry cu cheie persistentă → ERP → status → reconciliere\",\"db\":\"Registru mesaje, relație cu ID C_Order, versiunile catalogului/situației, erori fără date sensibile\",\"states\":\"primit → în așteptare → livrat / conflict → remediat → reconciliat\",\"fault\":\"Pauză după commit și înainte de ACK, mesaj vechi după nou, restaurare backup a canalului\",\"oracle\":\"Pentru toate mesajele fixture există rezoluție unică și diferența rămasă are ID explicit. Restaurarea A păstrează datele B și nu repetă efecte externe.\",\"owners\":\"A10 infrastructură, A06 comenzi, A07 evenimente\"}],\"c\":[{\"p\":1,\"t\":\"Traseul cabinet → firmă → canal\",\"s\":\"Deschide firma principală și secundară; intră în Magazin1, eMag și Trendyol ale firmei țintă.\",\"e\":\"URL-urile au segmentele exacte /CUI_A, /CUI_A/CUI_A sau /CUI_A/CUI_B și numele configurat al canalului. Antetul indică firma și canalul corecte.\",\"n\":\"Segment necunoscut, slash codificat și combinație cabinet B/firmă A nu deschid canalul A.\",\"a\":\"route tenancy\"},{\"p\":1,\"t\":\"Numele canalului și identitatea internă\",\"s\":\"Redenumește în fixture Magazin1 și creează același nume în altă firmă. Folosește apoi ambele URL.\",\"e\":\"Aceleași referințe interne și comenzi după redenumire; două firme cu numele identic se disting prin CUI.\",\"n\":\"Dublură în aceeași firmă este refuzată. Un link vechi se rezolvă numai conform politicii declarate și în firma corectă.\",\"a\":\"route channel\"},{\"p\":1,\"t\":\"Desfășurare per canal\",\"s\":\"Inventariază fiecare cabinet/firmă/canal activ și leagă site-ul de container, rută, imagine și proprietarul configurației.\",\"e\":\"100% din rândurile incluse au o instanță corespunzătoare, inclusiv canalele platformelor. Instanțele sunt distincte conform modelului cerut.\",\"n\":\"Oprește exclusiv fixture-ul A; B rămâne disponibil. O rută spre alt container produce eroare, nu alt magazin.\",\"a\":\"compose route spree\"},{\"p\":1,\"t\":\"Izolare stocare și cache\",\"s\":\"Inserează un canar sintetic numai în media, indexul și coșul A și caută-l în B după încălzirea cache-ului.\",\"e\":\"Zero apariții ale canarului în catalog B, fișiere B, coadă B, căutare B și sesiune B; se inventariază DB, Redis, Meili, ActiveStorage.\",\"n\":\"Manipulează parametrii tenant, Host și cookie în A; rezultatul nu dezvăluie B.\",\"a\":\"cms scope media\"},{\"p\":1,\"t\":\"Acces responsabil și comisionar\",\"s\":\"Compară funcțiile și răspunsurile a doi comisionari și unui gestionar pe același URL.\",\"e\":\"API aplică organizație, canal, proprietar și permisiune; comisionarul are catalog, comandă și situațiile proprii.\",\"n\":\"Utilizează URL de administrare direct; zero operații de administrare reușite din site.\",\"a\":\"rbac admin\"},{\"p\":2,\"t\":\"Mapare CPP și CPA\",\"s\":\"Publică două identități permanente pentru P1 bucată vs P1 ambalat și un set CPA fără CPP corespunzător; modifică SKU extern.\",\"e\":\"Fiecare variantă și linie de comandă păstrează ID-ul intern unic, inclusiv după schimbarea SKU/EAN.\",\"n\":\"SKU dublu sau produs fără mapare nu se substituie automat altui produs.\",\"a\":\"catalog fișa\"},{\"p\":2,\"t\":\"Preț și conversii pe canal\",\"s\":\"Configurează două canale cu monedă, taxă, UOM, discount și preț diferite; urmărește ERP, card produs și coș.\",\"e\":\"Pentru fiecare versiune, totalul brut, net, taxa, moneda și unitatea coincid în toate reprezentările la precizia configurată.\",\"n\":\"Trimite preț modificat în client și listă expirată; autoritatea comercială respinge sau recalculează, explicând schimbarea înaintea acceptării.\",\"a\":\"catalog fișa cart\"},{\"p\":2,\"t\":\"Alternative G3 și concurență la ultimul set\",\"s\":\"Pentru P1=P2=P3=120, două coșuri în două canale încearcă simultan 20 S1 și 40 S2.\",\"e\":\"Înainte de angajament se văd 20/40 alternative. Cantitățile acceptate respectă 6×S1 + 3×S2 ≤120 la fiecare componentă; refuzul afișează opțiunea disponibilă.\",\"n\":\"Răspuns stale din cache după ultimul angajament; nicio acceptare peste capacitate.\",\"a\":\"stock catalog order\"},{\"p\":2,\"t\":\"Dezactivare produs / ordonarea publicărilor\",\"s\":\"Publică v2 peste v1, apoi retrage produsul; livrează un mesaj v1 întârziat.\",\"e\":\"Lista și detaliul nu mai permit plasarea unei noi comenzi pentru oferta retrasă; istoricul comenzii vechi este lizibil.\",\"n\":\"Un eveniment vechi sau o invalidare cache repetată nu republică oferta.\",\"a\":\"fișa catalog stock\"},{\"p\":2,\"t\":\"Conversii B2B/B2C și segmente\",\"s\":\"Comparați cont anonim, grupă B2B și comisionar pentru aceeași ofertă în două canale.\",\"e\":\"Utilizatorii eligibili văd prețurile conform listei, pragurilor și grupurilor; prețul privat nu ajunge în răspuns public.\",\"n\":\"Solicitare anonimă către cache-ul populat din cont B2B și trecerea între două canale; niciun preț B2B divulgat.\",\"a\":\"catalog b2b cart\"},{\"p\":3,\"t\":\"Checkout complet cu adrese diferite\",\"s\":\"Plasează o comandă sintetică cu adresa de facturare în A și cea de livrare în B; corelează confirmarea cu C_Order și locațiile.\",\"e\":\"Un antet și numărul exact de linii cu cele două locații distincte; poziția și suma transportului ajung în ERP.\",\"n\":\"Lipsește adresa de livrare: pasul o cere înainte de confirmare, iar datele deja introduse sunt păstrate.\",\"a\":\"order address cart\"},{\"p\":3,\"t\":\"Recalculare înainte de confirmare\",\"s\":\"Schimbă preț și disponibil după deschiderea coșului; reîncearcă confirmarea.\",\"e\":\"Clientul vede suma recalculată și lipsa la stoc înainte de angajarea valorii noi; reluarea folosește valoarea confirmată.\",\"n\":\"Client furnizează total sau valută nepermise; nu apare document ERP cu totalul manipulabil.\",\"a\":\"order catalog cart\"},{\"p\":3,\"t\":\"Idempotent inclusiv după pierderea răspunsului\",\"s\":\"Simulează dublu clic și timeout după commit ERP pentru aceeași comandă; reia aceeași cheie.\",\"e\":\"Număr comenzi ERP=1 și aceeași referință este comunicată din nou. Două canale cu același ID extern își păstrează comenzile distincte.\",\"n\":\"Același ID extern cu payload schimbat produce conflict urmărit, fără suprascriere tăcută.\",\"a\":\"order spree\"},{\"p\":3,\"t\":\"Administrarea exclusiv în ERP\",\"s\":\"Pornește de la confirmarea clientului. Enumeră toate acțiunile site-ului și verifică butoanele, URL direct și API cu rolul comisionar.\",\"e\":\"Nicio etapă gestionar, pick, aviz, aprobare, AWB sau facturare nu poate fi declanșată de site/comisionar. ERP preia noua comandă pentru fluxul legitim.\",\"n\":\"Solicitare fabricată pentru schimbare stare, anulare logistică, emitere document sau livrare este respinsă fără efect în fixture.\",\"a\":\"admin order rbac\"},{\"p\":3,\"t\":\"Checkout accesibil și reluare la eroare\",\"s\":\"Parcurge coșul și confirmarea la 360px și desktop cu tastatura, focus vizibil și reader; întrerupe API în ultimul pas.\",\"e\":\"Etichetele, totalul, erorile și referința pot fi percepute fără mouse; datele rămân după eroare, iar reluarea nu comandă de două ori.\",\"n\":\"Eroare generică fără câmp indicat sau buton duplicabil se consemnează cu captură de focus și răspuns API.\",\"a\":\"cart order\"},{\"p\":4,\"t\":\"Raport pe proprietar în pagină și export\",\"s\":\"Creează două conturi comisionar în același canal și o vânzare vizibilă doar unuia; compară listă, detaliu, export și total.\",\"e\":\"Comisionarul A vede numai vânzările proprii și agregările lor. Totalul coincide cu A06 la data de referință.\",\"n\":\"Pentru ID sau cursorul de paginare aparținând lui B, nu se scurge nici totalul sau numărul comenzilor B.\",\"a\":\"orders rbac\"},{\"p\":4,\"t\":\"Revocarea accesului\",\"s\":\"Deschide contul A pe două sesiuni, revocă în fixture rolul său de pe canal și repetă solicitarea autorizată anterior.\",\"e\":\"După pragul documentat de revocare, atât API, cât și exportul sunt blocate pe ambele sesiuni. Celălalt comisionar funcționează normal.\",\"n\":\"Legătură veche, tab din cache sau cookie păstrat nu redeschid date private; verifică și refresh.\",\"a\":\"orders scope rbac\"},{\"p\":4,\"t\":\"Returul și situația comercială\",\"s\":\"De la o comandă eligibilă, solicită retur conform rolului, apoi confruntă situația după operarea returului în ERP și recalcularea comisionului.\",\"e\":\"Cererea poartă referința proprie. Situația afișează corecția primită din ERP; încasările și stocurile urmăresc documentele unice gestionate de A07.\",\"n\":\"Cerere repetată sau returul altei persoane nu creează document financiar suplimentar.\",\"a\":\"returns orders rbac\"},{\"p\":5,\"t\":\"Template Cesiro și teme independente\",\"s\":\"În două canale folosește două teme din aceeași familie; compară catalogul, coșul, checkout-ul și contractul comercial înainte și după schimbare.\",\"e\":\"Coșul, ID-urile și totalurile rămân identice pentru aceeași ofertă. Logica de checkout există într-un singur serviciu identificabil.\",\"n\":\"O temă incompletă nu devine activă, iar revenirea la versiunea anterioară păstrează coșul.\",\"a\":\"cart route commerce\"},{\"p\":5,\"t\":\"Preview specific eMag/Trendyol\",\"s\":\"Capturează în sandbox lista și pagina produs pentru model eMag și Trendyol după șabloanele de referință aprobate, la 360 și 1280px.\",\"e\":\"Responsabilul vede structura platformei, imagini, denumire, preț, atribute și stoc exact din fișa ce urmează a fi publicată. Captura include versiunea și diferențele față de referință.\",\"n\":\"Atribut obligatoriu lipsă e localizat lângă câmp; previzualizarea rămâne privată și nu publică la partener.\",\"a\":\"fișa theme catalog\"},{\"p\":5,\"t\":\"Publicare și integritatea conținutului\",\"s\":\"Include titlu cu markup, imagine indisponibilă și media autorizate; inspectează card, detaliu, fallback și versiunea ce va fi publicată.\",\"e\":\"Conținutul este afișat ca text sigur, imaginile au alternative și proveniență documentată. Un fișier privat/nelicențiat nu devine public.\",\"n\":\"URL media din alt tenant și JS în descriere nu returnează conținut privat sau executabil.\",\"a\":\"media catalog seo\"},{\"p\":6,\"t\":\"Disponibilitate pentru șase limbi\",\"s\":\"Parcurge catalogul, checkout-ul, mesajele de eroare și situația pentru ro/en/de/hu/bg/el, pe desktop și mobil.\",\"e\":\"Fiecare text este localizat sau poartă fallback-ul configurat și documentat. Nu apar chei brute. Parametrii comerciali nu se schimbă cu limba.\",\"n\":\"Traducere lipsă și caractere grecești, maghiare, diacritice române: căutarea, titlul și confirmarea păstrează textul corect.\",\"a\":\"lang cart seo\"},{\"p\":6,\"t\":\"Canonical și sitemap pe canal\",\"s\":\"Inspectează sitemap, robots, canonical și legăturile alternative pentru produs public, cont comisionar, coș și preview privat.\",\"e\":\"Numai URL public și al canalului corect apare în sitemap. Conturile/preview/export sunt protejate și neindexabile; răspunsul conține canonical coerent.\",\"n\":\"Nume de gazdă injectat sau imagine a altui tenant nu produce URL indexabil străin.\",\"a\":\"sitemap seo scope\"},{\"p\":6,\"t\":\"Preferințe și conversii marketing\",\"s\":\"Cu captură de trafic într-un mediu izolat, refuză, acceptă și retrage acordul opțional. Simulează apoi retry la confirmare.\",\"e\":\"Zero evenimente opționale până la consimțământul aplicabil și după retragere; o conversie urmărită per comandă eligibilă, corelată cu suma și canalul corecte.\",\"n\":\"Refuzul nu împiedică operațiile necesare ale coșului; refreshul sau campania altui canal nu repetă conversia.\",\"a\":\"commerce cart order\"},{\"p\":7,\"t\":\"Coada și exportul ordinelor eșuate\",\"s\":\"Oprește adaptorul simulat înainte și după commit și execută reconcilierea după reluare.\",\"e\":\"Pentru fiecare ID de comandă, registrul indică fie C_Order unic, fie eroare explicabilă și owner. Clientul păstrează referința și starea reîncercabilă.\",\"n\":\"Mesaj otrăvit nu blochează restul lotului, nu pierde originalul și nu expune adrese în log.\",\"a\":\"order spree\"},{\"p\":7,\"t\":\"Restaurarea unui singur canal\",\"s\":\"Adaugă date sintetice în A și B. Restaurează o copie A în mediu izolat, reconciliind până la cutoff declarați cu A10.\",\"e\":\"Canarul A și cheile de referință se refac; B păstrează starea. Reconcilierea nu retransmite comenzi conținând aceeași cheie.\",\"n\":\"Restaurare fără index sau media: diferența e identificată cu număr și procedură de reconstrucție înainte de redeschidere.\",\"a\":\"compose spree scope\"},{\"p\":7,\"t\":\"Proveniența instanțelor și sursa versiunii active\",\"s\":\"Pentru fiecare canal compară SHA Git, imagine, etichetă, montări, modul/JS efectiv, versiune și configurație. Repetă pentru Spree și reverse proxy.\",\"e\":\"Fiecare afirmație are versiunea ei: cod repo, cod activ, configurație, comportament. Diferențele rămân în registru cu proprietar și sursa lipsă.\",\"n\":\"Eticheta latest și unul din fișierele experimentale nu țin loc de dovadă asupra aplicației în uz.\",\"a\":\"compose route spree\"}]}
