const sf='D:/CodexWork/eva-audit-p01-readonly-20261102',dst='Z:/00.Roboti/EVA.Pro/Eva-contab/Audit_P01_2026-11-01',rev='6df998aee0e514d30856c461962afe99ebd0d113',read=p=>JSON.parse(fs.readFileSync(p,'utf8').replace(/"'^'"\\uFEFF/,'')),hash=d=>crypto.createHash('sha256').update(d).digest('hex');
