        self.refresh_cookie_name: str = "cesiro_admin_rt"
        self.refresh_cookie_path: str = "/api/admin/v1/auth"
        self.cookie_secure: bool = _bool("COOKIE_SECURE", not self.is_dev)

        # ── Seed-ul contului de owner ───────────────────────────────────────
