def _configured_hashes() -> list[str]:
    raw = os.environ.get("EXTERNAL_API_KEYS_SHA256", "")
    return [h.strip().lower() for h in raw.split(",") if re.fullmatch(r"[0-9a-fA-F]{64}", h.strip())]


def _require_key() -> None:
    hashes = _configured_hashes()
    if not hashes:
        raise _ExtError("API-ul extern nu este activat pe această instanță", 503, "disabled")
    auth = request.headers.get("Authorization", "")
    key = auth[7:].strip() if auth.lower().startswith("bearer ") else request.headers.get("X-Api-Key", "").strip()
    if not key:
        raise _ExtError("Lipsește cheia API (Authorization: Bearer <cheie> sau X-Api-Key)", 401, "unauthorized")
    digest = hashlib.sha256(key.encode()).hexdigest()
    if not any(hmac.compare_digest(digest, h) for h in hashes):
        raise _ExtError("Cheie API invalidă", 401, "unauthorized")


def _clean(value: Any) -> Any:
    if isinstance(value, dict):
        return {k: _clean(v) for k, v in value.items() if k not in _DROP_KEYS and not _SENSITIVE.search(k)}
    if isinstance(value, list):
        return [_clean(v) for v in value]
    return value


def _money(value: Any) -> Decimal:
    try:
        return Decimal(str(value if value is not None else 0))
    except Exception:  # noqa: BLE001
        return Decimal(0)


def _with_line_vat(item: dict[str, Any]) -> dict[str, Any]:
    """Liniile țin prețurile BRUTE (cu TVA) + cota; adăugăm netul și TVA-ul calculate (2 zecimale, rotunjire comercială)."""
    rate = _money(item.get("vat_rate"))
    q2 = Decimal("0.01")
    for src, net_key, vat_key in (("unit_price_gross_ron", "unit_price_net_ron", "unit_vat_ron"),
                                  ("line_total_gross_ron", "line_total_net_ron", "line_vat_ron")):
        gross = _money(item.get(src))
        net = (gross / (1 + rate)).quantize(q2, rounding=ROUND_HALF_UP) if rate > -1 else gross
        item[net_key] = float(net)
        item[vat_key] = float((gross - net).quantize(q2, rounding=ROUND_HALF_UP))
    item["vat_percent"] = float((rate * 100).quantize(Decimal("0.01")))
    return item


