def schema_has_site(session: Session) -> bool:
    """True dacă migrația 0086 („fațadă pe domeniu") e aplicată pe baza curentă.

    Codul Python e montat de pe disc în containerul viu (override de dev), deci poate
    rula ÎNAINTE de migrație: fără această gardă, un worker repornit ar cere coloana
    `site_overrides` și storefront-ul ar cădea. Rezultatul e cache-uit (True definitiv,
    False 60 s, ca după migrație + reload să se vadă fără alt restart)."""
    global _SITE_SCHEMA
    now = _time.monotonic()
    if _SITE_SCHEMA is not None and (_SITE_SCHEMA[1] or _SITE_SCHEMA[0] > now):
        return _SITE_SCHEMA[1]
    try:
        has = session.execute(text(
            "SELECT 1 FROM information_schema.columns WHERE table_schema = 'core'"
            " AND table_name = 'tenant_settings' AND column_name = 'site_overrides'"
        )).scalar() is not None
    except Exception:                                    # noqa: BLE001 - nu blocăm cererea
        try:
            session.rollback()                           # tranzacția să nu rămână «aborted» (aud2 r3)
    }


def site_hosts(session: Session, tenant_id: str) -> dict[str, list[str]]:
    """`{"ro": ["cesiro.ro", "www.cesiro.ro"]}` — gazdele cu etichetă de site, principala/
    cea mai scurtă prima. Gazdele fără etichetă (site-ul comun) nu apar."""
    if not schema_has_site(session):
        return {}
    rows = session.execute(
        text(
            """
            SELECT site, hostname FROM core.tenant_domains
             WHERE tenant_id = :tenant_id AND site IS NOT NULL
             ORDER BY site, is_primary DESC, length(hostname), hostname
            """
        ),
        {"tenant_id": tenant_id},
    ).all()
    hosts: dict[str, list[str]] = {}
    for site, hostname in rows:
        hosts.setdefault(str(site), []).append(str(hostname).lower())
    return hosts


def vat_rate(settings: dict[str, Any]) -> float:
    """Cota de TVA din setări. Implicit 21% (România, din 01.08.2025, Legea 141/2025)."""
    try:
        return float((settings.get("tax") or {}).get("vat_rate") or 0.21)
