#: Cotele STANDARD de TVA din UE (fracții) pentru vânzările la distanță către persoane fizice (regimul OSS):
#: se aplică cota ȚĂRII DE LIVRARE (proprietar, 13.10.2026: «la comenzile către client folosim cota de TVA a țării
#: respective: Grecia, Bulgaria, Ungaria»). Se pot suprascrie per țară din setări: `tax.vat_by_country` ({"BG": 0.2}).
EU_STANDARD_VAT: dict[str, float] = {
    "AT": 0.20, "BE": 0.21, "BG": 0.20, "CY": 0.19, "CZ": 0.21, "DE": 0.19, "DK": 0.25, "EE": 0.24,
    "ES": 0.21, "FI": 0.255, "FR": 0.20, "GR": 0.24, "HR": 0.25, "HU": 0.27, "IE": 0.23, "IT": 0.22,
    "LT": 0.21, "LU": 0.17, "LV": 0.21, "MT": 0.18, "NL": 0.21, "PL": 0.23, "PT": 0.23, "SE": 0.25,
    "SI": 0.22, "SK": 0.23,
}


def vat_rate_for_country(settings: dict[str, Any], country: str | None) -> float:
    """Cota de TVA pentru o vânzare cu livrare în `country`.

    Țara magazinului (`tax.home_country`, implicit RO) → cota magazinului (`vat_rate`). Altă țară UE → cota ei:
    întâi `tax.vat_by_country[țara]` din setări, altfel `EU_STANDARD_VAT`. `tax.destination_vat = false` revine la
    cota magazinului peste tot. Prețul cu TVA nu se schimbă (e cel afișat pe site); se schimbă doar partea de TVA
    din el (net = brut / (1 + cotă)).
    """
    tax = settings.get("tax") or {}
    home = str(tax.get("home_country") or "RO").upper()
    code = str(country or home).upper()
    if code == home or tax.get("destination_vat") is False:
        return vat_rate(settings)
    override = (tax.get("vat_by_country") or {}).get(code)
    try:
        if override is not None and 0 <= float(override) < 1:
            return float(override)
    except (TypeError, ValueError):
        pass
    return EU_STANDARD_VAT.get(code, vat_rate(settings))


def shipping_for_country(settings: dict[str, Any], country: str) -> float:
    rules = (settings.get("shipping_rules") or {}).get("rules") or []
    country = (country or "RO").upper()
    fallback = 0.0
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        if str(rule.get("country", "")).upper() == country:
            return float(rule.get("price_ron") or 0)
        if rule.get("country") == "*":
            fallback = float(rule.get("price_ron") or 0)
    return fallback


def allowed_countries(settings: dict[str, Any]) -> list[str]:
    countries = (settings.get("shipping_rules") or {}).get("countries")
    except Exception:                                 # noqa: BLE001
        return False


def delivery_price(settings: dict[str, Any], code: str, country: str,
                   products_gross_ron: float) -> float:
    """Costul livrării pentru metoda aleasă, cu pragul de transport gratuit aplicat."""
    for method in delivery_methods(settings, country):
        if method["code"] == code:
            free_over = method.get("free_over_ron")
            if free_over is not None and products_gross_ron >= float(free_over):
                return 0.0
            return round(float(method.get("price_ron") or 0), 2)
    return round(shipping_for_country(settings, country), 2)
