@ext_bp.get("/orders/<ref>")
def order_detail(ref: str):
    _require_key()
    want = (request.args.get("tenant") or "").strip()
    is_uuid = bool(re.fullmatch(r"[0-9a-fA-F-]{36}", ref))
    with _read_only_session() as session:
        _begin_read_only(session)
        for t in _tenants(session):
            if want and t["slug"] != want:
                continue
            _set_tenant(session, t["id"])
            row = session.execute(text(
                "SELECT o.id::text AS oid, to_jsonb(o) AS j FROM sales.orders o WHERE o.tenant_id = CAST(:t AS uuid) AND "
                + ("o.id = CAST(:r AS uuid)" if is_uuid else "o.order_number = :r")), {"t": t["id"], "r": ref}).first()
            if not row:
                continue
            oid, j = row
            order = _order_view(j, _items_for(session, [oid]).get(oid, []), t["slug"])
            for key, table, order_col in _ORDER_CHILDREN:
                if not _existing(session, table):
                    continue
                cols = session.execute(text(
                    "SELECT 1 FROM information_schema.columns WHERE table_schema = split_part(:t,'.',1) "
                    "AND table_name = split_part(:t,'.',2) AND column_name = 'order_id'"), {"t": table}).first()
                if not cols:
                    continue
                order_by = f" ORDER BY x.{order_col}" if order_col else ""
                rows = session.execute(text(f"SELECT to_jsonb(x) FROM {table} x WHERE x.order_id = CAST(:o AS uuid){order_by}"),
                                       {"o": oid}).scalars().all()
                order[key] = [_clean(r) for r in rows]
            if "returns" in order and order["returns"] and _existing(session, "sales.return_items"):
                ids = [r.get("id") for r in order["returns"] if r.get("id")]
                ritems = session.execute(text(
                    "SELECT to_jsonb(x) FROM sales.return_items x WHERE x.return_id::text = ANY(:ids)"),
                    {"ids": [str(i) for i in ids]}).scalars().all()
                order["return_items"] = [_clean(r) for r in ritems]
            session.rollback()
            return jsonify(order)
        session.rollback()
    raise _ExtError(f"Comanda '{ref}' nu există", 404, "not_found")
def _open_ctx(require_user: bool = False, cart_token: str | None = None):
    """Deschide o tranzacție cu `app.tenant_id` (+ `app.user_id` dacă e logat)."""
    slug = _tenant_slug()
    scope = session_scope()
    session = scope.__enter__()
    try:
        tenant_id = get_tenant_id(session, slug)
        if tenant_id is None:
            raise LookupError("unknown_tenant")
        from ..db import set_session_context

        set_session_context(session, tenant_id=tenant_id)
        identity = IdentityRepo(session, tenant_id)
        user = identity.user_from_session(_session_token())
        if user:
            set_session_context(session, user_id=user["user_id"], actor_type="customer",
                                actor_id=user["user_id"])
        elif require_user:
            raise PermissionError("missing_customer_session")
        # Politica `own_cart` a vizitatorului compară `cart_token_hash` cu acest
        # parametru de sesiune, deci trebuie setat ÎNAINTE de a citi/crea coșul —
        # inclusiv pentru tokenul proaspăt generat, care nu e încă în cookie.
        effective_token = cart_token or _cart_token()
        if effective_token:
            set_session_context(
                session, cart_token_hash=hash_cart_token(effective_token).hex()
            )
        return scope, _Ctx(session, tenant_id, slug, user)
    except Exception:
        scope.__exit__(*sys.exc_info())
        raise


