    @app.after_request
    def preview_no_store(response):
        """Cu cookie `eva_preview` (orice cale, inclusiv API-ul de catalog și
        `/api/offers/active`), răspunsul arată prețurile temei previzualizate: nu are
        voie în niciun cache comun. Înregistrat înaintea celorlalte `after_request`, deci
        rulează ULTIMUL și are ultimul cuvânt asupra `Cache-Control`."""
        from . import theme_preview

        if request.cookies.get(theme_preview.COOKIE):
            response.headers["Cache-Control"] = "private, no-store, max-age=0"
            vary = [v.strip() for v in (response.headers.get("Vary") or "").split(",") if v.strip()]
            if "Cookie" not in vary:
                vary.append("Cookie")
                response.headers["Vary"] = ", ".join(vary)
        return response

