    @bp.get("/settings/theme-preview-link")
    @require_role("editor")
    def theme_preview_link():
        """`?theme_id=<id>` → `{"url": "<PUBLIC_BASE_URL>/?preview=<token>", "expires_at",
        "theme_id", "ttl_seconds"}`.

        Link SEMNAT (`app.theme_preview`, salt „theme-preview", 60 min): storefront-ul
        arată tema cerută cu ofertele și prețurile EI (banner de previzualizare); coșul și
        checkout-ul rămân pe prețurile reale (tema efectivă).
        """
        from flask import request

        from .... import theme_preview
        from ..deps import current_admin

        theme_id = str(request.args.get("theme_id") or "").strip()
        valid = {str(t.get("id")) for t in _themes()}
        if theme_id not in valid:
            raise ApiError(f"Tema '{theme_id}' nu există", code="validation_failed",
                           status=400,
                           details={"theme_id": [f"Acceptate: {', '.join(sorted(valid))}"]})
        admin = current_admin()
        with tenant_db("editor") as (_session, tenant_id, _slug):
            try:
                token, expires_at = theme_preview.make_token(theme_id, tenant_id,
                                                             str(admin.get("id") or ""))
            except RuntimeError as exc:
                raise ApiError(str(exc), code="server_misconfigured", status=500) from exc
        url = f"{theme_preview.public_base_url()}/?preview={token}"
        response = jsonify({"url": url, "expires_at": expires_at.isoformat(),
                            "theme_id": theme_id, "ttl_seconds": theme_preview.TTL})
        return response

    @bp.get("/settings/theme-schedule")
    @require_role("editor")
    def get_theme_schedule():
        session.execute(
            text(
                """
                UPDATE identity.admin_users
                   SET failed_attempts = 0,
                       locked_until = NULL,
                       last_login_at = now(),
                       password_hash = COALESCE(:new_hash, password_hash)
                 WHERE id = :id
                """
            ),
            {"new_hash": new_hash, "id": row.id},
        )
        roles = _roles_for(session, row.id)
        access_token, expires_in = _issue_access(row, roles)
        refresh = _create_session_row(session, row.id)
        row = _load_admin(session, admin_id=row.id)
        payload = {
            "access_token": access_token,
            "token_type": "Bearer",
            "expires_in": expires_in,
            "user": _user_payload(row, roles),
        }

    settings = get_settings()
    max_age = settings.refresh_token_ttl if body.get("remember", True) else None
    response = make_response(jsonify(payload), 200)
    return _set_refresh_cookie(response, refresh, max_age or settings.refresh_token_ttl)


@admin_bp.post("/auth/refresh")
def refresh():
    settings = get_settings()
    token = request.cookies.get(settings.refresh_cookie_name, "")
    if not token:
        raise ApiError("Sesiune expirată", code="unauthorized", status=401)
    digest = hash_token(token)
def active_tenant() -> str:
    """Slug-ul tenantului pe care lucrează adminul (header `X-Tenant`)."""
    admin = current_admin()
    requested = (request.headers.get("X-Tenant") or request.args.get("tenant") or "").strip()
    roles: dict[str, str] = admin.get("roles") or {}
    if not requested:
        if admin.get("is_superadmin"):
            requested = get_settings().default_tenant
        elif len(roles) == 1:
            requested = next(iter(roles))
        else:
            requested = get_settings().default_tenant
    if not admin.get("is_superadmin") and requested not in roles:
        raise ApiError(f"Fără acces la tenantul '{requested}'", code="forbidden", status=403)
    return requested


def role_for(tenant_slug: str) -> str:
    admin = current_admin()
    if admin.get("is_superadmin"):
        return "owner"
    return (admin.get("roles") or {}).get(tenant_slug, "")


def require_auth(func: Callable) -> Callable:
    """Cere un access token valid. 401 (nu 403) la token expirat sau lipsă,
    ca interceptorul din SPA să poată încerca `POST /auth/refresh`."""

    @functools.wraps(func)
    def wrapper(*args: Any, **kwargs: Any):
        token = _bearer_token()
        if not token:
            raise ApiError("Autentificare necesară", code="unauthorized", status=401)
        try:
            payload = decode_access_token(token)
        except TokenError as exc:
            status = 500 if exc.code == "server_misconfigured" else 401
            raise ApiError(exc.message, code=exc.code, status=status) from exc
        g.admin = {
            "id": payload.get("sub"),
            "email": payload.get("email"),
            "is_superadmin": bool(payload.get("sa")),
            "roles": payload.get("roles") or {},
            "must_change_password": bool(payload.get("mcp")),
        }
        if g.admin["must_change_password"] and request.path not in PASSWORD_CHANGE_ALLOWED:
            raise ApiError(
                "Trebuie să îți schimbi parola înainte de a folosi panoul",
                code="password_change_required",
                status=403,
            )
        return func(*args, **kwargs)

    return wrapper


def require_role(minimum: str) -> Callable:
    """Rol minim pe tenantul activ: `viewer` < `editor` < `owner`."""

    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        @require_auth
        def wrapper(*args: Any, **kwargs: Any):
            tenant = active_tenant()
            have = role_for(tenant)
            if ROLE_ORDER.get(have, 0) < ROLE_ORDER.get(minimum, 99):
                raise ApiError(
                    f"Rol insuficient (ai '{have or 'niciunul'}', trebuie '{minimum}')",
                    code="forbidden",
                    status=403,
                )
            g.tenant_slug = tenant
            g.tenant_role = have
            return func(*args, **kwargs)

        return wrapper

    return decorator


def pagination() -> tuple[int, int]:
    """(page, per_page) validate, conform contractului cu panoul React."""
    try:
        page = max(1, int(request.args.get("page") or 1))
    except ValueError:
        page = 1
    try:
        per_page = int(request.args.get("per_page") or 50)
    except ValueError:
        per_page = 50
    return page, min(200, max(1, per_page))

