--  • RLS pe tenant (+ superadmin), grant complet admin API; storefront scrie prin webhook-ul public (INSERT / UPDATE / SELECT).
CREATE TABLE IF NOT EXISTS sales.inbound_messages (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id    uuid NOT NULL REFERENCES core.tenants(id) ON DELETE CASCADE,
  dedupe_key   text NOT NULL CHECK (length(dedupe_key) > 0),
  provider_id  text NOT NULL DEFAULT '',
  channel      text NOT NULL DEFAULT 'whatsapp',
  source       text NOT NULL DEFAULT 'webhook' CHECK (source IN ('webhook', 'poll', 'manual')),
  phone        text NOT NULL DEFAULT '',
  body         text NOT NULL DEFAULT '',
  received_at  timestamptz NOT NULL DEFAULT now(),
  raw          jsonb NOT NULL DEFAULT '{}'::jsonb,
  order_id     uuid REFERENCES sales.orders(id) ON DELETE SET NULL,
  intent       text NOT NULL DEFAULT 'other' CHECK (intent IN ('yes', 'no', 'other')),
  status       text NOT NULL DEFAULT 'stored' CHECK (status IN ('processed', 'stored', 'failed', 'ignored')),
  action       text NOT NULL DEFAULT 'none',
  error        text NOT NULL DEFAULT '',
  processed_at timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT inbound_messages_dedupe_uk UNIQUE (tenant_id, channel, dedupe_key)
);
CREATE INDEX IF NOT EXISTS inbound_messages_order_ix ON sales.inbound_messages (order_id, received_at DESC) WHERE order_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS inbound_messages_list_ix ON sales.inbound_messages (tenant_id, received_at DESC);

ALTER TABLE sales.inbound_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE sales.inbound_messages FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON sales.inbound_messages;
CREATE POLICY tenant_isolation ON sales.inbound_messages
  USING (tenant_id = core.current_tenant_id()) WITH CHECK (tenant_id = core.current_tenant_id());
DROP POLICY IF EXISTS superadmin_all ON sales.inbound_messages;
CREATE POLICY superadmin_all ON sales.inbound_messages
  USING (COALESCE(current_setting('app.superadmin', true), 'off') = 'on')
  WITH CHECK (COALESCE(current_setting('app.superadmin', true), 'off') = 'on');

DO $grants$
BEGIN
