/**
 * T22 (spec 74 §6.1a (1), (5); erata 74m; 71 Q-T-1, Q-74m-2) — preluarea T22 a comenzilor. La B-BE-3 (înaintea T35 L1)
 * conține DOAR garda căii T20 «Preiau din site» (A.8b), PURĂ, gata de chemat din {@code PreiaDinSite} de B-BE-1b (după
 * L1-M), care adaugă aici și {@code proceseaza(...)}: o fișă (sursă) cu {@code EVA_VanzariOnline='N'} salvat EXPLICIT de
 * «Salvez» e sărită — 0 cereri spre ea și rândul {@code vanzari.oprit} în jurnalul procesului; dacă TOATE fișele selectate
 * sunt sărite, procesul se termină cu eroarea {@code vanzari.oprit}, 0 cereri. {@code EVA_VanzariOnline} NULL (cabinetele
 * care n-au salvat niciodată setările T22) ⇒ calea T20 NESCHIMBATĂ.
 */
public final class PreluareComenziT22 {

    private PreluareComenziT22() {
    }

    /** Fișa e oprită (pur): DOAR {@code N} explicit; {@code null} / gol / {@code Y} ⇒ neoprită (calea T20 neschimbată). */
    public static boolean oprita(String vanzariOnline) {
        return vanzariOnline != null && "N".equals(vanzariOnline.strip());
    }

    /** Rezultatul gărzii: fișele de citit și numărul celor sărite. */
    public record Garda<T>(List<T> deCitit, int sarite) {
    }

    /**
     * Garda (pură): păstrează fișele neoprite, în ordine; fișele sărite se raportează prin {@code jurnal} (rândul
     * {@code vanzari.oprit} cu codul fișei). Dacă toate sunt sărite (și lista nu e goală) ⇒ {@link IllegalStateException} cu
     * eticheta {@code vanzari.oprit}, înainte de orice cerere.
     */
    public static <T> Garda<T> garda(List<T> fise, Function<T, String> vanzariOnline, Function<T, String> cod,
            java.util.function.Consumer<String> jurnal) {
        List<T> ok = new ArrayList<>();
        int sarite = 0;
        for (T f : fise) {
            if (oprita(vanzariOnline.apply(f))) {
                sarite++;
                jurnal.accept(Etichete.t("vanzari.preluare.fisa_oprita", cod.apply(f)));
            } else
                ok.add(f);
        }
        if (!fise.isEmpty() && ok.isEmpty())
            throw new IllegalStateException(Etichete.t("vanzari.oprit"));
        return new Garda<>(ok, sarite);
    }

    /** Valoarea {@code EVA_VanzariOnline} salvată pe fișa (sursa) firmei, sau {@code null} dacă nu a fost salvată niciodată. */

