/** POST /orders/{id}/status — validat de FSM in backend; UI-ul ofera doar tranzitiile permise. */
export async function changeOrderStatus(id: string, toStatus: OrderStatus, note?: string, confirmation?: string): Promise<Order> {
  if (config.useMocks) {
    const base = mockOrders.find((o) => o.id === id) ?? mockOrders[0];
    return mockDelay({
      ...base,
      status: toStatus,
      history: [
        ...base.history,
        {
          id: `oh-${Date.now()}`,
          from_status: base.status,
          to_status: toStatus,
          note: note ?? null,
          actor: 'admin@cesiro1.eva-org.com',
          created_at: new Date().toISOString(),
        },
      ],
    });
  }
  /* Starea „Anulată” cere `confirmation` = textul „anulare” tastat de om (anularea se face în doi pași). */
  return post<Order>(endpoints.orders.status(id), { to_status: toStatus, note, ...(confirmation ? { confirmation } : {}) });
}

export async function cancelOrder(id: string, reason: string, confirmation?: string): Promise<Order> {
  if (config.useMocks) return changeOrderStatus(id, 'cancelled', reason);
  return post<Order>(endpoints.orders.cancel(id), { reason, ...(confirmation ? { confirmation } : {}) });
}

